import React, { useEffect, useState } from "react";
import * as Curve from "@visx/curve";
import * as Shape from "@visx/shape";
import SimplexNoise from "simplex-noise";
import _ from "lodash";

import "../assets/css/circles.css";

function HomeAnimation(props) {
  // In pixels
  let period = 100;
  let amplitude = 40;

  // How often, in ms, to update state
  let animationSpeed = 1;

  let noiseStep = 0.005;

  let simplexNoise = new SimplexNoise(1);

  let width = 500;
  let height = 100;

  const [step, setStep] = useState(0);

  useEffect(
    () =>
      setInterval(
        () => setStep((currentStep) => currentStep + noiseStep),
        animationSpeed
      ),
    []
  );

  let calculateData = (value) => {
    let newData = [];

    // let pushData = (arrayOfFuncs) => {
    //   _.times(width, (loop) => {
    //     let transformedStep = loop + value;
    //     for (let func of arrayOfFuncs) {
    //       let result = amplitude * func((Math.PI / period) * transformedStep);
    //       newData.push([loop, result + 50]);
    //     }
    //   });
    // };

    // let arrayOfFuncs = [
    //   Math.sin,
    //   (x) => Math.sin(2 * x),
    //   (x) => Math.cos(2 * x),
    //   (x) => Math.cos(x),
    // ];

    // pushData(arrayOfFuncs);

    _.times(width / 10, (x) => {
      let step = x + value;
      let func = (x) => amplitude * Math.sin((Math.PI / period) * x);

      let y = x + 1;
      let noiseVal = 50 * simplexNoise.noise2D(step, Math.atan2(step));

      newData.push([x * 10, noiseVal + 50]);
    });

    return newData;
  };

  return (
    <svg width={width} height={height}>
      <Shape.LinePath
        curve={Curve.curveCatmullRom}
        data={calculateData(step)}
        stroke="black"
        strokeWidth={5}
      />
    </svg>
  );
}

export default HomeAnimation;
